() => {
  window.__pdfErrors = [];
  window.__pdfLogs = [];
  if (!window.__consoleHooked) {
    const origError = console.error;
    const origWarn = console.warn;
    const origLog = console.log;
    const fmt = (a) => {
      try {
        if (a instanceof Error) return a.message + ' | ' + (a.stack || '');
        if (typeof a === 'object') return JSON.stringify(a);
        return String(a);
      } catch (e) { return 'unstringifiable:' + typeof a; }
    };
    console.error = (...args) => { window.__pdfErrors.push(args.map(fmt).join(' ')); origError.apply(console, args); };
    console.warn = (...args) => { window.__pdfLogs.push('[warn] ' + args.map(fmt).join(' ')); origWarn.apply(console, args); };
    window.addEventListener('error', (e) => { window.__pdfErrors.push('[window.onerror] ' + e.message); });
    window.addEventListener('unhandledrejection', (e) => { window.__pdfErrors.push('[unhandledrejection] ' + fmt(e.reason)); });
    window.__consoleHooked = true;
  }
  return 'hooked';
}

() => {
  // 检查页面上计算样式中包含 oklab 的元素（找出残留来源）
  const all = document.querySelectorAll('*');
  const hits = [];
  const props = ['color','backgroundColor','borderColor','borderTopColor','borderBottomColor','borderLeftColor','borderRightColor','outlineColor','boxShadow','textShadow','fill','stroke','backgroundImage'];
  for (const el of all) {
    const cs = getComputedStyle(el);
    for (const p of props) {
      const v = cs[p];
      if (v && v.includes('oklab')) {
        hits.push({tag: el.tagName, cls: (el.className||'').toString().slice(0,60), prop: p, value: v.slice(0,120)});
        if (hits.length > 15) return hits;
      }
    }
  }
  return hits;
}

